/* VCD dumping functions */
MOD_mkTbNocRouterPerf & mkTbNocRouterPerf_backing(tSimStateHdl simHdl)
{
  static MOD_mkTbNocRouterPerf *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTbNocRouterPerf(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
