{
  (mkTbNocRouterPerf_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkTbNocRouterPerf::dump_VCD(tVCDDumpType dt)
{
  (mkTbNocRouterPerf_instance->dump_VCD)(dt, vcd_depth(sim_hdl), mkTbNocRouterPerf_backing(sim_hdl));
}
